// Look up an estimate for a building from our seed list. Matches the
// building's canonical name first, then each alias, all normalized.
// Returns null if no seed estimate exists.
export function lookupBuildingEstimate(building) {
  if (!building) return null;
  const tries = [building.name, ...(building.aliases || []), building.address];
  for (const t of tries) {
    if (!t) continue;
    const hit = TORONTO_BUILDING_ESTIMATES[normalize(t)];
    if (hit) return hit;
  }
  return null;
}

// Rating tier label per the spec. 85+ A, 78-84 B, 70-77 C, 62-69 D premium,
// 55-61 E very premium.
export function getEstimateRatingTier(score) {
  if (score >= 85) return { tier: 'A',  label: 'Strong estimated value',         color: '#1a5c34', bg: '#f0f7f2', border: '#a8d5b5' };
  if (score >= 78) return { tier: 'B',  label: 'Good estimated value',           color: '#1a5c34', bg: '#f0f7f2', border: '#a8d5b5' };
  if (score >= 70) return { tier: 'C',  label: 'Fair estimated value',           color: '#7a4f00', bg: '#fdf8f0', border: '#e8c97a' };
  if (score >= 62) return { tier: 'D',  label: 'Premium priced estimate',        color: '#b45309', bg: '#fffbeb', border: '#fde68a' };
  return                  { tier: 'E',  label: 'Very premium priced estimate',   color: '#8b1a1a', bg: '#fdf0f0', border: '#e8a8a8' };
}
